<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Support\LegacyResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Throwable;
class LoadLogController extends Controller
{
 private function user(Request $r){return $r->attributes->get('jwt_user');}
 public function today(Request $r){try{$q=DB::table('load_logs as ll')->join('equipment as e','e.id','=','ll.equipment_id')->where('ll.shift',$r->input('shift'))->whereDate('ll.logged_at',now()->toDateString());if($r->filled('plant'))$q->where('e.plant',$r->input('plant'));if($r->filled('department'))$q->where('e.department',$r->input('department'));return response()->json(['success'=>true,'data'=>$q->pluck('ll.equipment_id')->map(fn($v)=>(string)$v)->all()]);}catch(Throwable $e){return $this->err($e);}}
 public function last24(Request $r){try{$q=DB::table('load_logs as ll')->join('equipment as e','e.id','=','ll.equipment_id')->join('users as u','u.id','=','ll.logged_by')->select('ll.*','e.name as equipment_name','e.code as equipment_code','e.kw_capacity','e.load_100pct','e.critical_load','u.full_name as logged_by_name')->where('ll.logged_at','>=',now()->subHours(24));if($r->filled('plant'))$q->where('e.plant',$r->input('plant'));if($r->filled('department'))$q->where('e.department',$r->input('department'));return response()->json(['success'=>true,'data'=>$q->orderByDesc('ll.logged_at')->get()->map(fn($x)=>LegacyResponse::normalize($x))->all()]);}catch(Throwable $e){return $this->err($e);}}
 public function store(Request $r){$eid=$r->input('equipment_id');$shift=$r->input('shift');if(!$eid||!$shift)return response()->json(['success'=>false,'message'=>'equipment_id and shift required'],400);try{if(DB::table('load_logs')->where('equipment_id',$eid)->where('shift',$shift)->whereDate('logged_at',now()->toDateString())->exists())return response()->json(['success'=>false,'message'=>'Load log already submitted for this shift'],409);$id=DB::table('load_logs')->insertGetId(['equipment_id'=>$eid,'plant'=>$r->input('plant'),'department'=>$r->input('department')?:null,'shift'=>$shift,'logged_by'=>$this->user($r)->id,'red_load'=>$r->input('red_load')?:null,'yellow_load'=>$r->input('yellow_load')?:null,'blue_load'=>$r->input('blue_load')?:null,'remarks'=>$r->input('remarks')?:null,'logged_at'=>now()]);return response()->json(['success'=>true,'data'=>['id'=>$id]]);}catch(Throwable $e){return $this->err($e);}}
 private function err(Throwable $e){return response()->json(['success'=>false,'message'=>$e->getMessage()],500);}
}
